## 🚀 Código Refatorado (Completo)

Para que este código funcione perfeitamente, você deve garantir que os IDs e URLs (aqueles que estão nos comentários `// <- CONFIGURAÇÃO`) sejam substituídos pelos seus valores reais.

```javascript
// =================================================================
// ⚙️ CONFIGURAÇÕES (Idealmente em um arquivo .env ou config)
// =================================================================
const CONFIG = {
    LOG_CHANNEL_ID: '1264758034979360860', // <- SUBSTITUA PELO ID REAL DO CANAL DE LOGS
    ADMIN_ROLE_ID: '995792293309190184', // <- SUBSTITUA PELO ID DO CARGO ADMIN/MANAGE
    STAFF_CARGO_ID: '995154994183548953', // <- SUBSTITUA PELO ID DO CARGO DE COMPRA
    DEFAULT_INACTIVITY_DELAY: 1000 * 60 * 5, // 5 minutos
    CART_TIMEOUT_MS: 600000, // 10 minutos para interações no carrinho
    PAYMENT_CHECK_INTERVAL_MS: 60000, // Checa status de pagamento a cada 60 segundos
};

// =================================================================
// 🧩 DEPENDÊNCIAS
// =================================================================
const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');
const crypto = require('crypto');
const { Cart, Payment } = require('../database/models/Models');

/**
 * Classe responsável por gerenciar o ciclo de vida e o estado do carrinho de compras.
 * @class CartClass
 */
class CartClass {
    /**
     * Cria uma instância de CartClass.
     * @param {Discord.Client} client - Instância do cliente Discord.
     * @param {Discord.Interaction} interaction - Interação inicial (se disponível).
     * @param {String} productId - ID do produto.
     * @param {Object} productData - Dados do produto.
     * @param {Object} user - Objeto do usuário.
     */
    constructor(client, interaction, productId, productData, user) {
        // --- Estado Principal ---
        this.client = client;
        this.interaction = interaction;
        this.productId = productId;
        this.productData = productData;
        this.user = user; // Garantindo que o usuário seja injetado

        // --- Variáveis de Sessão do Carrinho ---
        this.paymentProcessor = new PaymentProcessor();
        this.inactivityTimer = null;
        this.cartId = crypto.randomBytes(10).toString('hex');
        this.channel = null;
        this.quantity = 1;
        this.selectedPlan = null;
        this.days = 0; // Inicializado em 0
        this.message = null; // Armazena o objeto do mensageiro do carrinho
        this.paymentId = null; // ID do pagamento gerado

        // --- Configurações ---
        this.inactivityDelay = CONFIG.DEFAULT_INACTIVITY_DELAY;
    }

    /**
     * Envia um log para o canal de logs configurado.
     * @param {EmbedBuilder} embed - A embed a ser enviada.
     */
    async sendLog(embed) {
        const logChannelId = CONFIG.LOG_CHANNEL_ID;
        if (logChannelId) {
            const logChannel = this.client.channels.cache.get(logChannelId);
            if (logChannel) {
                try {
                    await logChannel.send({ embeds: [embed] });
                } catch (error) {
                    console.error(`[LOG] Erro ao enviar log para ${logChannelId}:`, error);
                }
            } else {
                console.warn(`[LOG] Canal de logs não encontrado: ${logChannelId}`);
            }
        }
    }

    /**
     * Cria uma embed de encerramento por inatividade.
     * @returns {EmbedBuilder}
     */
    createInactivityEmbed() {
        return new EmbedBuilder()
            .setColor('#FF0000')
            .setDescription(`### 🙁 Seu carrinho foi encerrado\nOlá ${this.user.tag},\n\nSeu carrinho foi cancelado devido à inatividade. Você pode retomar sua compra a qualquer momento. Esperamos vê-lo novamente em breve. \n\n-# Atenciosamente, Nyox Applications.`);
    }

    /**
     * Cria uma resposta para carrinho já existente.
     * @param {Discord.GuildChannel} channel - Canal do carrinho.
     * @returns {object} - Componente de resposta.
     */
    createCartOpenEmbed(channel) {
        return {
            content: `Você já tem um carrinho criado!`,
            ephemeral: true,
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setStyle(ButtonStyle.Link)
                        .setLabel("💰 Carrinho")
                        .setURL(channel.url)
                )
            ]
        };
    }

    /**
     * Cria uma embed de sucesso ao abrir o carrinho.
     * @param {String} channelURL - URL do canal do carrinho.
     * @returns {object} - Componente de resposta.
     */
    createCartSuccessEmbed(channelURL) {
        return {
            content: "",
            embeds: [
                new EmbedBuilder()
                    .setColor('#060A18')
                    .setDescription(`### Olá, ${this.user.tag}, seu carrinho foi aberto!\n\`🌟\` Você está prestes a adquirir o ${this.productData.productName}, um sistema exclusivo da **Nyox Applications** com a melhor qualidade do mercado.\n-# Para ser redirecionado ao carrinho, clique no botão abaixo.`)
            ],
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setLabel("Acessar carrinho")
                        .setStyle(ButtonStyle.Link)
                        .setEmoji("🛒")
                        .setURL(channelURL)
                )
            ]
        };
    }

    /**
     * Cria uma embed para seleção de plano.
     * @returns {object} - Componente de resposta.
     */
    createPlanSelectionEmbed() {
        const { preco } = this.productData;
        const planFields = [];

        // Estrutura de campos para os planos
        const plans = [
            { key: 'mensal', label: "📅 Plano Mensal", icon: '📅', days: 30 },
            { key: 'quizena', label: "🗓️ Plano Quinzenal", icon: '🗓️', days: 15 },
            { key: 'semanal', label: "📆 Plano Semanal", icon: '📆', days: 7 },
        ];

        plans.forEach(plan => {
            if (preco[plan.key].onoff) {
                const price = preco[plan.key].preco;
                planFields.push({
                    name: plan.label,
                    value: `**${plan.days} dias** - R$${price}`,
                    inline: true
                });
            }
        });

        return {
            content: `${this.user} <@&${CONFIG.ADMIN_ROLE_ID}>`, // Melhor usar o ID de um papel específico
            embeds: [
                new EmbedBuilder()
                    .setTitle("🛒 Sistema de Compras")
                    .setColor("#00BFFF")
                    .setAuthor({
                        name: this.client.user.username,
                        iconURL: this.client.user.displayAvatarURL({ dynamic: true })
                    })
                    .setDescription(`👋 Olá, ${this.user.tag}! Falta pouco para finalizar sua compra. Escolha um dos planos abaixo para continuar:`)
                    .addFields(planFields)
            ],
            components: [this.createPlanButtons()]
        };
    }

    /**
     * Cria os botões de seleção de plano e cancelamento.
     * @returns {ActionRowBuilder}
     */
    createPlanButtons() {
        const row = new ActionRowBuilder();
        const { preco } = this.productData;

        // Botões de Plano
        const plans = [
            { key: 'mensal', label: "30 Dias", emoji: "📅" },
            { key: 'quizena', label: "15 Dias", emoji: "📅" },
            { key: 'semanal', label: "7 Dias", emoji: "📆" },
        ];

        plans.forEach(plan => {
            if (preco[plan.key].onoff) {
                row.addComponents(
                    new ButtonBuilder()
                        .setEmoji(plan.emoji)
                        .setLabel(plan.label)
                        .setStyle(ButtonStyle.Primary)
                        .setCustomId(`${plan.key}Cart`) // Nome padronizado
                );
            }
        });

        // Botão de Cancelar
        row.addComponents(
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setEmoji("❌")
                .setLabel("Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
        );

        return row;
    }

    /**
     * Define ou redefine um timer para inatividade.
     * @param {Function} callback - Função a ser executada ao timeout.
     * @param {Number} delay - Duração do delay em milissegundos.
     */
    setInactivityTimer(callback, delay = this.inactivityDelay) {
        if (this.inactivityTimer) {
            clearTimeout(this.inactivityTimer);
        }
        this.inactivityTimer = setTimeout(callback, delay);
    }

    /**
     * Lida com o cancelamento por inatividade.
     */
    async handleInactivity() {
        console.log(`[Cart] Carrinho do usuário ${this.user.id} expirou por inatividade.`);

        try {
            // Envia mensagem privada
            await this.user.send({
                embeds: [this.createInactivityEmbed()],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId("resumeCart")
                            .setLabel("Retomar Compra")
                            .setStyle(ButtonStyle.Secondary)
                    )
                ]
            });

            // Cria o Embed de Log
            const logEmbed = new EmbedBuilder()
                .setTitle("📝 Carrinho Expirado")
                .setColor("#FF0000")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild ? this.interaction.guild.name : 'N/A' })
                .addFields(
                    { name: '👥 Usuário:', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho ID:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 Expirou em:', value: new Date().toLocaleString() },
                    { name: '❔ Motivo:', value: `Inatividade (Aguardando ${this.inactivityDelay / 60000} minutos)` }
                );

            await this.sendLog(logEmbed);

            // Limpeza do canal e do banco de dados
            if (this.channel) {
                try {
                    await this.channel.delete();
                    await Cart.deleteOne({ channelId: this.channel.id });
                    console.log(`[Cart] Canal de carrinho ${this.channel.id} deletado e registro removido.`);
                } catch (error) {
                    console.error("Erro ao deletar canal ou registro do carrinho:", error);
                }
            }

        } catch (error) {
            console.error("[Cart] Erro grave ao lidar com inatividade:", error);
        }
    }

    /**
     * Lida com o pagamento aprovado.
     * @param {String} paymentId - ID do pagamento.
     */
    async handleApprovedPayment(paymentId) {
        try {
            const cartRecord = await Cart.findOne({ channelId: this.channel.id });
            if (!cartRecord) {
                 throw new Error("Cartão não encontrado no banco de dados.");
            }

            // 1. Atualiza status no BD
            cartRecord.status = "Processando";
            await cartRecord.save();

            // 2. Concede o cargo
            const staffCargoClientId = CONFIG.STAFF_CARGO_ID;
            if (staffCargoClientId) {
                const member = this.client.guilds.cache.get(this.interaction?.guildId)?.members.cache.get(this.user.id);
                if (member) {
                    await member.roles.add(staffCargoClientId).catch(e => console.warn("Usuário já possuía o cargo ou falha na concessão:", e.message));
                }
            }

            // 3. Mensagens finais e limpeza
            if (this.message) {
                await this.message.edit({ content: `✅ Pagamento Aprovado \n🆔 ID da Compra: ${this.cartId}` });

                // Envia a mensagem final de entrega do bot
                await this.channel.send({
                    content: `${this.user}`,
                    embeds: [
                        new EmbedBuilder()
                            .setTitle("🚀 Pagamento Aprovado - Pronto para Deploy")
                            .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                            .setDescription(`**O pagamento foi aprovado! Para que possamos configurar seu bot, por favor, envie os seguintes dados:**\n\n- **Nome desejado na aplicação**\n- **ID do dono do bot**\n- **Token do Bot**\n\n**⚠ | MANTENHA O TOKEN SEGURO! Não compartilhe.**`)
                    ],
                    components: [
                        new ActionRowBuilder().addComponents(
                            new ButtonBuilder()
                                .setLabel("Enviar Bot / Redeem")
                                .setEmoji("🎉")
                                .setStyle(ButtonStyle.Primary)
                                .setCustomId(`${this.selectedPlan}_${this.days * this.quantity}_${this.productId}_redeemBot`),
                            new ButtonBuilder()
                                .setLabel("Portal Desenvolvedor")
                                .setEmoji("🤖")
                                .setStyle(ButtonStyle.Link)
                                .setURL("https://discord.com/developers/applications/"),
                            new ButtonBuilder()
                                .setLabel("Tutorial")
                                .setEmoji("🔗")
                                .setStyle(ButtonStyle.Link)
                                .setURL("https://docs.nyox.tech/tutorials/createapp")
                        )
                    ]
                });
            }

            // 4. Limpeza
            await this.channel.bulkDelete(50); // Deleta mensagens antigas
            await Cart.deleteOne({ channelId: this.channel.id });

        } catch (error) {
            console.error("[Cart] Erro grave ao lidar com pagamento aprovado:", error);
        }
    }

    /**
     * Lida com a criação e processamento do pagamento.
     * @param {Object} paymentResponse - Retorno da criação do pagamento (Mockado ou Real).
     */
    async processPayment(paymentResponse) {
        try {
            if (!paymentResponse) {
                throw new Error("Resposta de pagamento inválida. Verifique o PaymentProcessor.");
            }

            const { id, attachment, pixCopyPasteCode } = paymentResponse;

            // Atualiza o Payment ID na instância
            this.paymentId = id;

            // Calcula o total de forma segura
            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            // 1. Atualiza a mensagem com o resumo e detalhes do pagamento
            await this.message.edit({
                embeds: [
                    new EmbedBuilder()
                        .setTitle("🛒 Resumo do Carrinho")
                        .setDescription(`\n\`📨\` **ID do Pedido**: ${this.cartId}\n\`📦\` **Produto**: ${this.productData.productName}\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias\n\`💸\` **Total**: R$${totalAmount}`)
                        .setColor('#00BFFF')
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId("pixCopyPaste")
                            .setLabel("📋 Código Copiar/Colar")
                            .setEmoji("💰")
                            .setStyle(ButtonStyle.Secondary),
                        new ButtonBuilder()
                            .setCustomId("cancelPayment")
                            .setLabel("❌ Cancelar Pedido")
                            .setStyle(ButtonStyle.Danger)
                    )
                ]
            });

            // 2. Envia o QR Code/Anexo
            if (attachment) {
                await this.channel.send({ files: [attachment] });
            }

            // 3. Monitora o status do pagamento
            const checkPaymentStatus = setInterval(async () => {
                try {
                    // ATENÇÃO: MOCK SUBSTITUÍDO PELO STATUS REAL DO SEU PROCESSADOR DE PAGAMENTO
                    // REMOVA 'const status = "approved"' E USE O MÉTODO REAL
                    const status = await this.paymentProcessor.checkPaymentStatus(id); 

                    console.log(`[Payment] - Status do pagamento (${id}): ${status}`);

                    if (status === "approved") {
                        clearInterval(checkPaymentStatus);
                        await this.handleApprovedPayment(id);
                    } else if (status === "cancelled" || status === "failed") {
                        clearInterval(checkPaymentStatus);
                        await this.handleInactivity(); // Ou um cancelamento específico
                    }
                } catch (error) {
                    console.error("[Payment] Erro ao verificar status de pagamento:", error.message);
                }
            }, CONFIG.PAYMENT_CHECK_INTERVAL_MS); 

        } catch (error) {
            console.error("[Cart] Erro ao processar pagamento:", error);
            // Tenta notificar o usuário sobre a falha
            if (this.message) {
                await this.message.edit({ content: `❌ Ocorreu um erro ao iniciar o processo de pagamento. Por favor, contate o suporte.` });
            }
        }
    }

    /**
     * Finaliza a compra e gera os dados de pagamento.
     * @param {Discord.Interaction} interaction - Interação do botão.
     */
    async finalizePurchase(interaction) {
        try {
            clearTimeout(this.inactivityTimer);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            const paymentOptions = {
                amount: Number(totalAmount),
                description: `Compra - ${this.user.tag} - ${this.productData.productName}`,
                first_name: this.user.firstName || this.user.tag,
                email: this.user.email || 'paymentsinbox@nyox.tech',
                otherData: {
                    notification_url: "https://nyox.tech/api/notifications"
                }
            };

            // 1. Cria o pagamento (Usando o mock ou seu método real)
            // IMPORTANTE: O 92690421680 é um MOCK. Substitua pela sua lógica real.
            const paymentResponse = await this.paymentProcessor.getPayment(92690421680, paymentOptions);

            if (!paymentResponse || !paymentResponse.id) {
                throw new Error("Falha na API: Não foi possível gerar o pagamento.");
            }

            // 2. Salva o pagamento e atualiza o carrinho no BD
            const paymentRecord = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: paymentOptions.amount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email,
                cartId: this.cartId // Adiciona o cartId ao registro de pagamento para rastreio
            });
            await paymentRecord.save();

            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { paymentId: paymentResponse.id, status: "Aguardando Pagamento" },
                { new: true }
            );

            // 3. Processa e monitora
            await this.processPayment(paymentResponse);

        } catch (error) {
            console.error("[Cart] Erro ao finalizar pedido:", error);
            if (interaction) {
                await interaction.reply({ content: `🚨 Erro: Ocorreu um erro ao processar seu pedido. ${error.message || 'Tente novamente mais tarde.'}`, ephemeral: true });
            }
        }
    }

    /**
     * Atualiza a quantidade no carrinho (adicionar ou remover).
     * @param {Discord.Interaction} interaction - Interação do botão.
     * @param {String} action - 'add' ou 'remove'.
     */
    async updateCartQuantity(interaction, action) {
        try {
            if (action === "add") {
                this.quantity += 1;
            } else if (action === "remove") {
                this.quantity -= 1;

                if (this.quantity < 1) {
                    this.quantity = 1; // Impede que fique negativo
                    return interaction.reply({
                        embeds: [new EmbedBuilder().setDescription("❌ Você não pode diminuir mais do que 1 item.")],
                        ephemeral: true
                    });
                }
            }

            // 1. Atualiza o BD
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            // 2. Atualiza a visualização no Discord
            await interaction.update(this.cratePlanItens());

            // 3. Reinicia o timer
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);

        } catch (error) {
            console.error("[Cart] Erro ao atualizar quantidade do carrinho:", error);
        }
    }

    /**
     * Lida com o cancelamento da ordem pelo usuário.
     * @param {Discord.Interaction} interaction - Interação do botão.
     */
    async handleCancellation(interaction) {
        try {
            clearTimeout(this.inactivityTimer);

            const logEmbed = new EmbedBuilder()
                .setTitle("❌ Cancelamento de Carrinho")
                .setColor("#800000")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name })
                .addFields(
                    { name: '👥 Usuário:', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho ID:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 Data/Hora:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` },
                    { name: '❔ Motivo:', value: `Cancelado pelo usuário.` }
                );

            await this.sendLog(logEmbed);

            // 1. Limpeza de BD
            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                // 2. Limpeza de Discord
                await this.channel.delete();
            }
            await interaction.reply({ content: "✅ Seu pedido foi cancelado com sucesso.", ephemeral: true });

        } catch (error) {
            console.error("[Cart] Erro ao lidar com cancelamento:", error);
            await interaction.reply({ content: "❌ Houve um erro ao tentar cancelar seu pedido. Verifique o log.", ephemeral: true });
        }
    }

    /**
     * Lida com o cancelamento do pagamento.
     * @param {Discord.Interaction} interaction - Interação do botão.
     */
    async handleCancelPayment(interaction) {
        try {
            clearTimeout(this.inactivityTimer);

            const logEmbed = new EmbedBuilder()
                .setTitle("❌ Cancelamento de Pagamento")
                .setColor("#800000")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name })
                .addFields(
                    { name: '👥 Usuário:', value: `${this.user.tag} - \`${this.user.id}\`` },
                    { name: '📝 Carrinho ID:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '❔ Motivo:', value: `Pagamento cancelado pelo usuário.` },
                    { name: '🕒 Data/Hora:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` }
                );

            await this.sendLog(logEmbed);

            // Tenta cancelar o pagamento (necessita do paymentId)
            if (this.paymentId) {
                await this.paymentProcessor.cancelPayment(this.paymentId);
            } else {
                console.warn("[Cart] Tentativa de cancelar pagamento sem Payment ID.");
            }

            // Limpeza
            if (this.channel) {
                await this.channel.delete();
                await Cart.deleteOne({ channelId: this.channel.id });
            }
            await interaction.reply({ content: "✅ Seu pagamento foi cancelado e o pedido foi encerrado.", ephemeral: true });

        } catch (error) {
            console.error("[Cart] Erro ao cancelar pagamento:", error);
            await interaction.reply({ content: "❌ Erro ao cancelar o pagamento. O pedido pode permanecer em processamento. Contate o suporte.", ephemeral: true });
        }
    }

    /**
     * Cria o carrinho e inicia o processo.
     */
    async createCart() {
        try {
            // 1. Verifica Carrinho Existente
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity;
                    this.selectedPlan = existingCart.selectedPlan;

                    // Determina os dias do plano existente
                    if (existingCart.selectedPlan === "mensal") this.days = 30;
                    else if (existingCart.selectedPlan === "quizena") this.days = 15;
                    else if (existingCart.selectedPlan === "semanal") this.days = 7;

                    return this.interaction ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) : true;
                }
            }

            // 2. Inicia o novo carrinho
            await this.interaction.reply({ content: "Aguarde um momento, estou preparando seu carrinho...", ephemeral: true });

            // Cria Thread (Canal privado)
            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras para compra de serviço.",
                members: [this.user.id],
                permissionOverwrites: [
                    {
                        id: this.user.id,
                        allow: ["ViewChannel", "SendMessages"], // Permite ver e enviar mensagens
                        deny: []
                    },
                    {
                        id: this.interaction.guild.id,
                        deny: ["ViewChannel"] // Esconde de outros membros
                    }
                ]
            });

            this.channel = thread;

            // 3. Persiste o carrinho no BD (UPSERT)
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando Plano" // Novo estado de inicialização
                },
                { upsert: true, new: true }
            );

            // 4. Define timer e inicia a conversa no thread
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);

            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);

            // Inicia o processo chamando handlePlanSelection (forçamos o 30 dias, ou pode ser apenas uma chamada de UI)
            // Aqui, assumimos que a primeira interação seria a seleção de plano, mas para iniciar, só mostramos os planos.
            // Se você precisa forçar, ajuste essa chamada.
        } catch (error) {
            console.error("[Cart] Erro crítico ao criar carrinho:", error);
            if (this.interaction) {
                 await this.interaction.reply({ content: "🚨 Desculpe, houve um erro ao iniciar seu carrinho. Por favor, tente novamente.", ephemeral: true });
            }
        }
    }

    /**
     * Executa o listener de interações do carrinho.
     */
    async run(start) {
        await this.createCart();

        // Cria o coletor de componentes
        const collector = this.channel.createMessageComponentCollector({ 
            componentType: ComponentType.Button, 
            time: CONFIG.CART_TIMEOUT_MS 
        });

        collector.on("collect", async (btnInteraction) => {
            // Validação básica
            if (btnInteraction.user.id !== this.user.id || !this.channel) return;

            await btnInteraction.deferUpdate(); // Previne feedback duplo e mantém a UI responsiva

            // Reinicia o timer ANTES de qualquer ação
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);

            try {
                switch (btnInteraction.customId) {
                    case "7DiasCart":
                    case "15DiasCart":
                    case "30DiasCart":
                        await this.handlePlanSelection(btnInteraction);
                        break;

                    case "cancelOrder":
                        await this.handleCancellation(btnInteraction);
                        break;

                    case "addToCart":
                        await this.updateCartQuantity(btnInteraction, "add");
                        break;

                    case "removeFromCart":
                        await this.updateCartQuantity(btnInteraction, "remove");
                        break;

                    case "finalizePurchase":
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case "pixCopyPaste":
                    case "qrCode":
                        await this.handlePaymentDetailsRequest(btnInteraction);
                        break;

                    case "cancelPayment":
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    case "resumeCart":
                         // Lógica para retomar o carrinho caso ele tenha expirado (ex: enviar uma mensagem de reabertura)
                         await btnInteraction.reply({ content: "Seu carrinho foi reativado. Você pode continuar comprando.", ephemeral: true });
                         break;

                    default:
                        console.log(`[Cart] CustomId desconhecido: ${btnInteraction.customId}`);
                }
            } catch (error) {
                console.error("[Cart] Erro durante o processamento da interação:", error);
                await btnInteraction.editReply({ content: `❌ Ocorreu um erro ao processar sua ação. Por favor, tente novamente.`, ephemeral: true });
            }
        });

        collector.on("end", async () => {
            console.log(`[Cart] Coletor de interações finalizado para o carrinho ${this.cartId}.`);
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        });
    }

    /**
     * Lida com a seleção de plano após a exibição dos planos.
     * @param {Discord.Interaction} interaction - Interação do botão.
     */
    async handlePlanSelection(interaction) {
        const customId = interaction.customId;
        let planKey, days;

        // Mapeamento robusto
        if (customId.includes("30DiasCart")) {
            planKey = "mensal";
            days = 30;
        } else if (customId.includes("15DiasCart")) {
            planKey = "quizena";
            days = 15;
        } else if (customId.includes("7DiasCart")) {
            planKey = "semanal";
            days = 7;
        } else {
            return;
        }

        // 1. Atualiza o estado da instância
        this.selectedPlan = planKey;
        this.days = days;

        // 2. Atualiza o BD
        await Cart.findOneAndUpdate(
            { channelId: this.channel.id },
            { quantity: this.quantity, status: "Aguardando Pagamento", selectedPlan: this.selectedPlan },
            { new: true }
        );

        // 3. Atualiza a mensagem no Discord para mostrar detalhes e botões de compra
        await this.message.edit(this.cratePlanItens());

        // 4. Log
        this.logPlanSelection(interaction);

        // 5. Reinicia o timer
        this.setInactivityTimer(() => {
            this.handleInactivity();
        }, this.inactivityDelay);
    }

    /**
     * Helper para logar a seleção de plano.
     * @param {Discord.Interaction} interaction 
     */
    logPlanSelection(interaction) {
        const logEmbed = new EmbedBuilder()
            .setTitle("✅ Plano Selecionado")
            .setColor("#00BFFF")
            .setAuthor({
                name: this.client.user.username,
                iconURL: this.client.user.displayAvatarURL({ dynamic: true })
            })
            .setFooter({
                text: this.interaction.guild ? this.interaction.guild.name : 'N/A'
            })
            .addFields(
                { name: "👥 Usuário", value: `${this.user.tag} - \`${this.user.id}\``, inline: false },
                { name: "🛒 Carrinho ID", value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                { name: "💰 Plano Escolhido", value: `**${this.selectedPlan.toUpperCase()}** (${this.days} dias)`, inline: false }
            );
        this.sendLog(logEmbed);
    }

    /**
     * Cria a embed com os detalhes finais do pedido e botões de ação.
     * @returns {object} - Componente de resposta.
     */
    cratePlanItens() {
        const { preco } = this.productData;
        const total = Number(preco[this.selectedPlan].preco * this.quantity).toFixed(2);

        const embed = new EmbedBuilder()
            .setTitle(`📦 Detalhes do Pedido: ${this.productData.productName}`)
            .setDescription(`Olá, ${this.user.tag}! Você selecionou o plano **${this.capitalize(this.selectedPlan)}**.\n\n\`✨\` **Produto**: ${this.productData.productName}\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias\n\`💰\` **Valor Total**: R$${total}`)
            .setColor("#060A18")
            .setThumbnail(this.productData.imageUrl || '') // Adicionar thumbnail se houver URL
            .addFields(
                { name: 'ID do Carrinho', value: `\`${this.cartId}\``, inline: true }
            );

        const buttonsRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId("addToCart")
                .setLabel("➕ Adicionar")
                .setStyle(ButtonStyle.Primary),
            new ButtonBuilder()
                .setCustomId("removeFromCart")
                .setLabel("➖ Remover")
                .setStyle(ButtonStyle.Secondary),
            new ButtonBuilder()
                .setCustomId("finalizePurchase")
                .setLabel("💳 Confirmar e Pagar")
                .setStyle(ButtonStyle.Success)
                .setEmoji("✅"),
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setLabel("❌ Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
                .setEmoji("❌")
        );

        return { embeds: [embed], components: [buttonsRow] };
    }

    /**
     * Solicita os detalhes do pagamento (QR Code / Copia e Cola).
     * @param {Discord.Interaction} interaction 
     */
    async handlePaymentDetailsRequest(interaction) {
        // Assumindo que o Payment ID já existe no objeto `this`
        if (!this.paymentId) {
            return interaction.reply({ content: "❌ O processo de pagamento ainda não foi iniciado ou foi cancelado.", ephemeral: true });
        }

        try {
            // Você deve passar o paymentId para o PaymentProcessor para buscar os detalhes
            const paymentDetails = await this.paymentProcessor.getPaymentDetails(this.paymentId); 

            if (interaction.customId === "qrCode" && paymentDetails.attachment) {
                // Envia o anexo
                await interaction.reply({ files: [paymentDetails.attachment], ephemeral: true });
            } else if (interaction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                // Envia o código
                await interaction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
            } else {
                 await interaction.reply({ content: "⚠️ Detalhes do pagamento não encontrados neste momento. Por favor, aguarde ou tente novamente.", ephemeral: true });
            }
        } catch (error) {
            console.error("[Cart] Erro ao buscar detalhes do pagamento:", error);
            await interaction.reply({ content: "🚨 Desculpe, ocorreu um erro ao acessar os detalhes do pagamento. Contate o suporte.", ephemeral: true });
        }
    }

    /**
     * Helper para capitalizar strings.
     * @param {String} str 
     * @returns {String}
     */
    capitalize(str) {
        if (typeof str !== 'string' || str.length === 0) return '';
        return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    }
}

module.exports = CartClass;
